recalc();if(!initialShared){const requested=view.chapter;const seg=guideSegment();if(seg){view.t=!new URLSearchParams(location.search).has('chapter')&&!view.vignette&&requested==='integration'?seg.start:seg.instant;view.start=dayStart(view.t);view.camera=seg.camera||chapters.find(x=>x.id===requested).camera;view.event=seg.event||null;refreshSamples();snap=sim.at(view.t)}}playing=false;lastTick=performance.now();draw();import('./scene.js').then(({createScene})=>{scene=createScene($('scene'),{onPick:inspect,onHover:help.component});scene.setChapter?.(view.chapter);scene.setView(view.camera);scene.update(hardware,snap);scene.setOverlays(view.overlays);scene.highlight(view.inspect||'')}).catch(err=>{console.error(err);$('scene').textContent='The 3D renderer could not start. The engineering workspaces remain available.'});requestAnimationFrame(tick);if(initialShared&&view.chronological)fullAudit();
